namespace RecipeHub.Data;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread crushed tomatoes\n4. Add torn mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil and olive oil",
            Ratings = new List<int> { 5, 4, 5, 4 }
        },
        new Recipe
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast, Yogurt, Garam masala, Tomato sauce, Heavy cream, Onion, Garlic, Ginger, Cilantro",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or bake chicken until charred\n3. Sauté onion, garlic, and ginger\n4. Add tomato sauce and cream\n5. Simmer with chicken pieces\n6. Garnish with cilantro",
            Ratings = new List<int> { 5, 5, 4 }
        },
        new Recipe
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Taco seasoning",
            Steps = "1. Brown ground beef\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm taco shells\n5. Assemble with toppings",
            Ratings = new List<int> { 4, 4, 3, 5 }
        },
        new Recipe
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti al dente\n2. Crisp guanciale in a pan\n3. Whisk eggs with grated pecorino and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture\n6. Serve immediately with extra pecorino",
            Ratings = new List<int> { 5, 5, 5 }
        },
        new Recipe
        {
            Id = 5, Title = "Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles, Shrimp, Tofu, Bean sprouts, Peanuts, Lime, Fish sauce, Tamarind paste, Eggs",
            Steps = "1. Soak rice noodles in warm water\n2. Make sauce with tamarind, fish sauce, and sugar\n3. Stir-fry shrimp and tofu\n4. Add eggs, scramble\n5. Add noodles and sauce\n6. Top with peanuts, bean sprouts, and lime",
            Ratings = new List<int> { 4, 5, 4 }
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt",
            Steps = "1. Mash avocados to desired consistency\n2. Dice onion, tomato, jalapeño, and cilantro\n3. Mix all ingredients together\n4. Add lime juice and salt to taste\n5. Serve with tortilla chips",
            Ratings = new List<int> { 5, 4, 5, 5 }
        },
        new Recipe
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Ingredients = "Coconut milk, Green curry paste, Chicken, Thai basil, Bamboo shoots, Bell pepper, Fish sauce, Sugar",
            Steps = "1. Heat coconut cream until oil separates\n2. Fry curry paste until fragrant\n3. Add chicken and cook through\n4. Pour in coconut milk\n5. Add vegetables and bamboo shoots\n6. Season with fish sauce and sugar\n7. Top with Thai basil",
            Ratings = new List<int> { 4, 4, 5 }
        },
        new Recipe
        {
            Id = 8, Title = "Butter Chicken", Category = "Indian",
            Ingredients = "Chicken thighs, Butter, Tomato purée, Cream, Garam masala, Fenugreek leaves, Garlic, Ginger",
            Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or pan-fry chicken\n3. Make sauce with butter, tomato, and spices\n4. Add cream and fenugreek\n5. Simmer chicken in sauce\n6. Serve with naan or rice",
            Ratings = new List<int> { 5, 5, 4, 5 }
        }
    };

    private int _nextId = 9;

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAll() => _recipes.ToList();

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating >= 1 && rating <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }
}

