@page "/category/{CategoryName}"
@using RecipeHub.Data
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>
<p><a href="/">← Back to Categories</a></p>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.Ratings.Count ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Data
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
    <a href="/">← Back to Home</a>
}
else
{
    <p><a href="/category/@recipe.Category">← Back to @recipe.Category</a></p>

    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: @recipe.Category</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[1] == '.' && char.IsDigit(text[0]))
                text = text[3..];
            else if (text.Length > 3 && text[2] == '.' && char.IsDigit(text[0]) && char.IsDigit(text[1]))
                text = text[4..];
            <li>@text.Trim()</li>
        }
    </ol>

    <hr />

    <h3>Rate this Recipe</h3>
    <p>Average: ⭐ @recipe.AverageRating.ToString("F1") (@recipe.Ratings.Count ratings)</p>

    <StarRating RecipeId="recipe.Id" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Data
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "filled" : "")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              role="button"
              title="@star star(s)">
            ★
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 2rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star-rating .star.filled {
        color: #ffc107;
    }
    .star-rating .star:hover {
        color: #ffdb4d;
    }
</style>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private int hoverRating;
    private bool submitted;

    private void SubmitRating(int rating)
    {
        selectedRating = rating;
        RecipeService.AddRating(RecipeId, rating);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Data
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p><a href="/">← Back to Home</a></p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted successfully!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added.</p>
        <a href="/recipe/@submittedId" class="btn btn-primary">View your recipe</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit another</button>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            @if (showValidation && string.IsNullOrWhiteSpace(title))
            {
                <div class="text-danger">Title is required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="category" class="form-select">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Thai">Thai</option>
                <option value="American">American</option>
                <option value="French">French</option>
                <option value="Japanese">Japanese</option>
                <option value="Other">Other</option>
            </InputSelect>
            @if (showValidation && string.IsNullOrWhiteSpace(category))
            {
                <div class="text-danger">Category is required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="ingredients" class="form-control" rows="4"
                placeholder="List ingredients separated by commas, e.g., Flour, Sugar, Butter, Eggs" />
            @if (showValidation && string.IsNullOrWhiteSpace(ingredients))
            {
                <div class="text-danger">Ingredients are required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="steps" class="form-control" rows="6"
                placeholder="Write each step on a new line, e.g.&#10;1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
            @if (showValidation && string.IsNullOrWhiteSpace(steps))
            {
                <div class="text-danger">Steps are required.</div>
            }
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted;
    private bool showValidation;
    private int submittedId;

    private void HandleSubmit()
    {
        showValidation = true;

        if (string.IsNullOrWhiteSpace(title) ||
            string.IsNullOrWhiteSpace(category) ||
            string.IsNullOrWhiteSpace(ingredients) ||
            string.IsNullOrWhiteSpace(steps))
        {
            return;
        }

        var recipe = new Recipe
        {
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };

        RecipeService.AddRecipe(recipe);
        submittedId = recipe.Id;
        submitted = true;
    }

    private void Reset()
    {
        title = string.Empty;
        category = string.Empty;
        ingredients = string.Empty;
        steps = string.Empty;
        submitted = false;
        showValidation = false;
    }
}

